        "cs", "cr", "cg", "ds", "dr", "du", "dg",
        "ss",
        "ls", "la", "lg", "qs", "qg",
        "os", "pc", "pg", "oa", "ot", "og", "oc", "oh", "bp", "bq", "qp", "rp", "rg",
