        "mr", "mg", "mh", "ms", "mx", "rh", "ra", "ma", "mo", "lp", "pa",
        "ce", "ci", "cl", "cb", "cv", "ct", "cd", "pd", "hd",
        "fs", "fx", "fr", "fi", "oi", "od",
        "fb", "fp", "fq",
        "br",
        "hm", "fm", "fh",
        "fa", "fe", "ah",
        "ea", "eh",
        "ts", "tk", "tg", "tx",
        "ep", "fw",
        "ru",
    ):
        fail(EXIT_INPUT, "INPUT")

